#!/usr/bin/env bash
# 作者: kejiqing
# 打出可点击的桌面应用。REGION=china 使用国内构建镜像。
set -euo pipefail
cd "$(dirname "$0")/.."
REGION="${REGION:-else}"
export REGION
CARGO_MIRROR="$PWD/.cargo/config.toml"

if [ "$REGION" = "china" ]; then
  export RUSTUP_DIST_SERVER="${RUSTUP_DIST_SERVER:-https://rsproxy.cn}"
  export RUSTUP_UPDATE_ROOT="${RUSTUP_UPDATE_ROOT:-https://rsproxy.cn/rustup}"
  export NPM_CONFIG_REGISTRY="${NPM_CONFIG_REGISTRY:-https://registry.npmmirror.com}"
  mkdir -p "$(dirname "$CARGO_MIRROR")"
  cat >"$CARGO_MIRROR" <<'EOF'
# generated by scripts/build.sh for REGION=china
[source.crates-io]
replace-with = "rsproxy-sparse"

[source.rsproxy-sparse]
registry = "sparse+https://rsproxy.cn/index/"
EOF
elif [ -f "$CARGO_MIRROR" ] && grep -qE "generated by scripts/(dev|build)\.sh for REGION=china" "$CARGO_MIRROR"; then
  rm -f "$CARGO_MIRROR"
fi

if [ ! -d node_modules ]; then
  npm install
fi
if [ ! -d ui/node_modules ]; then
  npm install --prefix ui
fi

# 只要 macOS .app，点一下就能开。不打 dmg / 安装器。
npm run build -- --bundles app

APP_SRC="$PWD/src-tauri/target/release/bundle/macos/Supone Tunnel.app"
APP_DST="/Applications/Supone Tunnel.app"
HELPER_SRC="$PWD/src-tauri/target/release/supone-priv"
if [ "$(uname -s)" = "Darwin" ] && [ -d "$APP_SRC" ]; then
  # 停内核 helper：与主程序同目录，运行时拷到 data/bin 再一次性 setuid。
  if [ ! -f "$HELPER_SRC" ]; then
    (cd src-tauri && cargo build --release --bin supone-priv)
  fi
  if [ -f "$HELPER_SRC" ]; then
    cp "$HELPER_SRC" "$APP_SRC/Contents/MacOS/supone-priv"
    chmod +x "$APP_SRC/Contents/MacOS/supone-priv"
  else
    echo "警告: 未找到 supone-priv，TUN 停内核仍可能每次要密码" >&2
  fi
  rm -rf "$APP_DST"
  cp -R "$APP_SRC" "$APP_DST"
  xattr -dr com.apple.quarantine "$APP_DST" 2>/dev/null || true
  echo "已安装到 $APP_DST"
fi
